begin;
set local role service_role;
do $$
declare owner_uuid uuid; cid uuid:=gen_random_uuid(); sid uuid; sid2 uuid; opt uuid; opt2 uuid; r jsonb; denied boolean;
begin
 if public.mqd_first_friday('2026-11-01')!='2026-11-06'::date then raise exception 'November schedule'; end if;
 if public.mqd_first_friday('2027-01-01')!='2027-01-01'::date then raise exception 'First-day Friday schedule'; end if;
 if public.mqd_first_friday('2027-05-01')!='2027-05-07'::date then raise exception 'Late first Friday schedule'; end if;
 if (public.mqd_first_friday('2026-11-01')::timestamp at time zone 'America/New_York')-interval '1 minute'!='2026-11-06T04:59:00Z'::timestamptz then raise exception 'EST cutoff'; end if;
 if (public.mqd_first_friday('2027-05-01')::timestamp at time zone 'America/New_York')-interval '1 minute'!='2027-05-07T03:59:00Z'::timestamptz then raise exception 'EDT cutoff'; end if;
 select owner_id into owner_uuid from public.mqd_monthly_config;
 if owner_uuid is null then raise exception 'Missing owner configuration'; end if;
 insert into public.mqd_contests(id,user_id,title,closes_at,opens_at,announces_at,round_month)
 values(cid,owner_uuid,'ROLLBACK ONLY monthly test',now()+interval '1 hour',now()-interval '1 day',now()+interval '61 minutes','2099-01-01');
 sid:=public.mqd_monthly_submit(cid,null,null,'Entry one','one@example.invalid','data:image/png;base64,aA==',null,'');
 if jsonb_array_length(public.mqd_contest_public(cid)->'options')!=0 then raise exception 'Pending entry leaked'; end if;
 denied:=false;begin perform public.mqd_monthly_submit(cid,null,null,'Duplicate email','ONE@example.invalid','data:image/png;base64,aA==',null,'');exception when others then denied:=true;end;
 if not denied then raise exception 'Duplicate entry accepted'; end if;
 denied:=false;begin perform public.mqd_monthly_submit(cid,owner_uuid,gen_random_uuid(),'Other account design','bad@example.invalid','data:image/png;base64,aA==',null,'');exception when others then denied:=true;end;
 if not denied then raise exception 'Unowned design accepted'; end if;
 opt:=public.mqd_monthly_review(sid,owner_uuid,'approve','');
 if public.mqd_monthly_review(sid,owner_uuid,'approve','')!=opt then raise exception 'Approval retry not idempotent'; end if;
 sid2:=public.mqd_monthly_submit(cid,null,null,'Entry two','two@example.invalid','data:image/png;base64,aA==',null,'');
 opt2:=public.mqd_monthly_review(sid2,owner_uuid,'approve','');
 if not public.mqd_contest_vote(cid,opt,'browser-one','network-one') then raise exception 'First vote failed'; end if;
 if public.mqd_contest_vote(cid,opt2,'browser-one','network-one') then raise exception 'Repeat vote counted'; end if;
 perform public.mqd_contest_vote(cid,opt2,'browser-two','network-two');
 r:=public.mqd_contest_public(cid,false);
 if (r->>'total')::int!=2 or r::text like '%contact_email%' or r::text like '%design_snapshot%' then raise exception 'Totals or privacy failed'; end if;
 update public.mqd_contests set closes_at=now()-interval '1 minute',announces_at=now()+interval '1 minute' where id=cid;
 if public.mqd_contest_public(cid)->'outcome'->>'status'!='awaiting_reveal' then raise exception 'Winner revealed early'; end if;
 denied:=false;begin perform public.mqd_contest_vote(cid,opt,'late-voter','network-three');exception when others then denied:=true;end;
 if not denied then raise exception 'Late vote accepted'; end if;
 denied:=false;begin perform public.mqd_monthly_submit(cid,null,null,'Late','late@example.invalid','data:image/png;base64,aA==',null,'');exception when others then denied:=true;end;
 if not denied then raise exception 'Late entry accepted'; end if;
 denied:=false;begin perform public.mqd_monthly_review(sid,owner_uuid,'disqualify','test');exception when others then denied:=true;end;
 if not denied then raise exception 'Final result could be altered'; end if;
 update public.mqd_contests set announces_at=now()-interval '1 second' where id=cid;
 if public.mqd_contest_public(cid)->'outcome'->>'status'!='tie' then raise exception 'Tie selected a sole winner'; end if;
 update public.mqd_contests set closes_at=now()+interval '1 minute',announces_at=now()+interval '2 minutes' where id=cid;
 perform public.mqd_monthly_review(sid2,owner_uuid,'disqualify','Not eligible');
 if (public.mqd_contest_public(cid)->>'total')::int!=1 then raise exception 'Disqualified votes remain eligible'; end if;
 update public.mqd_contests set closes_at=now()-interval '1 minute',announces_at=now()-interval '1 second' where id=cid;
 r:=public.mqd_contest_public(cid);
 if r->'outcome'->>'status'!='winner' or r->'outcome'->'designs'->0->>'label'!='Entry one' then raise exception 'Wrong winner'; end if;
 if has_table_privilege('anon','public.mqd_contest_submissions','SELECT') or has_table_privilege('authenticated','public.mqd_contest_submissions','SELECT') then raise exception 'Private table access exposed'; end if;
 if has_function_privilege('anon','public.mqd_monthly_review(uuid,uuid,text,text)','EXECUTE') or has_function_privilege('authenticated','public.mqd_monthly_submit(uuid,uuid,uuid,text,text,text,jsonb,text)','EXECUTE') then raise exception 'Private RPC exposed'; end if;
end $$;
rollback;
select 'Monthly schedule, approval, vote, privacy and winner tests passed; all fixtures rolled back.' result;
